export type Difficulty = "foundational" | "intermediate" | "advanced";

export interface Topic {
  id: string;
  title: string;
  shortDesc: string;
  difficulty: Difficulty;
  readTimeMin: number;
  keyPoints: string[];
  content: string; // placeholder — fill content here
  codeExample?: {
    language: string;
    filename: string;
    code: string;
  };
  tags: string[];
}

export interface Module {
  id: string;
  title: string;
  description: string;
  topics: Topic[];
}

export interface Domain {
  id: "frontend" | "backend" | "infrastructure" | "devops" | "cheat" | "nutshell";
  title: string;
  tagline: string;
  description: string;
  color: string; // accent color class
  iconName: string; // lucide-react icon name
  topics: Topic[];
  modules: Module[];
}

