// -- DTO: Data Transfer Object with validation --
import { IsString, IsEmail, MinLength } from "class-validator";

export class CreateUserDto {
    @IsString()                                 // Validation decorator
    @MinLength(2)
    name: string;

    @IsEmail()
    email: string;
}
